export function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export function seedVenues() {
  return ROWS.map((row, i) => ({
    ...row,
    state: 'VIC',
    country: 'Australia',
    contactName: '',
    payType: '',
    status: 'active',
    visibility: 'shared',
    ownerId: null,
    source: 'seed',
    addedAt: new Date(Date.now() - (i + 3) * 86400000).toISOString(),
  }));
}

